import { getClub, canonicalClubId } from './clubsDb.js'
import { getNation } from './nationsDb.js'
import { prepareDeck, shuffle } from './deck.js'
import { countryLabel, continentLabel } from './geoLabels.js'

// Kits live outside the bundle (a server volume in production) together with manifest.json
// generated by `npm run kits:manifest`; VITE_KITS_BASE_URL can point them at another host.
const KITS_BASE = (import.meta.env.VITE_KITS_BASE_URL || '/kits').replace(/\/+$/, '')

// { [season]: [{ league, dir, kind, region, clubs, altKits? }] } — empty until loadKitsManifest() resolves
let kitsManifest = {}
let manifestPromise = null

const isSafePath = p => typeof p === 'string' && p.length > 0 && !p.split('/').some(seg => seg === '..' || seg === '')
const isString = v => typeof v === 'string' && v.length > 0

// Drops malformed entries instead of failing on them — the manifest is data from the server.
function sanitizeManifest(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) throw new Error('Invalid kits manifest')
  const out = {}
  for (const [season, leagues] of Object.entries(raw)) {
    if (!/^\d{4}_\d{2}$/.test(season) || !Array.isArray(leagues)) continue
    const valid = leagues.filter(l => l && isString(l.league) && isSafePath(l.dir) && isString(l.region)
      && (l.kind === 'club' || l.kind === 'nation') && Array.isArray(l.clubs))
      .map(l => ({
        ...l,
        clubs: l.clubs.filter(c => c && isString(c.id) && Array.isArray(c.kits)),
        altKits: Object.fromEntries(Object.entries(l.altKits || {})
          .map(([id, files]) => [id, Array.isArray(files) ? files.filter(isSafePath) : []])),
      }))
    if (valid.length) out[season] = valid
  }
  return out
}

export function loadKitsManifest() {
  manifestPromise ??= fetch(`${KITS_BASE}/manifest.json`, { cache: 'no-cache' })
    .then(res => {
      if (!res.ok) throw new Error(`Kits manifest request failed: ${res.status}`)
      return res.json()
    })
    .then(raw => { kitsManifest = sanitizeManifest(raw) })
    .catch(err => {
      manifestPromise = null // allow a retry instead of caching the failure
      throw err
    })
  return manifestPromise
}

// '/kits' + 'europe/England/Premier League/2025_26' + 'man_city_1.png' with every segment URL-encoded
function kitUrl(dir, file) {
  return [KITS_BASE, ...`${dir}/${file}`.split('/').map(encodeURIComponent)].join('/')
}

export function getSeasons() {
  return Object.keys(kitsManifest).sort().reverse()
}

// Every manifest entry with its season: [{ season, league, kind, region, ... }]
function allEntries() {
  return Object.entries(kitsManifest).flatMap(([season, leagues]) => leagues.map(l => ({ season, ...l })))
}

// Continents (kind 'club') or confederations (kind 'nation') that have kits, sorted by label.
export function getRegions(kind) {
  return [...new Set(allEntries().filter(e => e.kind === kind).map(e => e.region))]
    .sort((a, b) => regionLabel(kind, a).localeCompare(regionLabel(kind, b), 'pl'))
}

export function regionLabel(kind, region) {
  return kind === 'club' ? continentLabel(region) : region
}

// Club leagues of the given continents (any season), sorted by Polish country name, then league.
export function getLeaguesIn(regions) {
  const leagues = allEntries().filter(e => e.kind === 'club' && regions.includes(e.region)).map(e => e.league)
  return [...new Set(leagues)].sort((a, b) =>
    leagueCountryLabel(a).localeCompare(leagueCountryLabel(b), 'pl') || leagueName(a).localeCompare(leagueName(b), 'pl'))
}

// Seasons (newest first) in which at least one of the competitions has kits.
export function getSeasonsFor(competitions) {
  return getSeasons().filter(s => (kitsManifest[s] || []).some(l => competitions.includes(l.league)))
}

// Club league keys have the form "<Country> - <League>"; for nations the key is the confederation (see vite.config.js).
export function leagueName(league) {
  return league.split(' - ').slice(1).join(' - ') || league
}

export function leagueCountry(league) {
  return league.split(' - ')[0]
}

export function leagueCountryLabel(league) {
  return countryLabel(leagueCountry(league).toLowerCase())
}

// '2025_26' → '25/26' (short) or '2025/2026' (long)
export function seasonShort(season) {
  const [from, to] = season.split('_')
  return `${from.slice(-2)}/${to}`
}

export function seasonLong(season) {
  const [from, to] = season.split('_')
  return `${from}/${from.slice(0, 2)}${to}`
}

// Number of kit images the quiz can draw from for the given scope.
export function countKits(clubs, kitTypes) {
  const typeNums = kitTypes.filter(t => typeof t === 'number')
  const includeAlt = kitTypes.includes('alt')
  return clubs.reduce((sum, c) => {
    const main = (c.kits || [1, 2, 3]).filter(k => typeNums.includes(k)).length
    const alt = includeAlt ? (c.altUrls || []).length : 0
    return sum + main + alt
  }, 0)
}

export function buildClubList(selectedSeasons = [], selectedLeagues = []) {
  const seasons = selectedSeasons.length ? selectedSeasons : getSeasons()
  const seen = new Set()
  const result = []

  for (const season of seasons) {
    const leagueEntries = kitsManifest[season] || []
    for (const { league, dir, kind = 'club', clubs = [], altKits = {} } of leagueEntries) {
      if (selectedLeagues.length && !selectedLeagues.includes(league)) continue
      const lookup = kind === 'nation' ? getNation : getClub
      const canonical = kind === 'nation' ? id => id : canonicalClubId
      // Alt files may use a different name than the main kits (bahia_1b.png vs bahia1.png)
      const altByClub = {}
      for (const [altId, files] of Object.entries(altKits)) (altByClub[canonical(altId)] ||= []).push(...files)
      for (const { id, prefix, sep = '_', kits = [1, 2, 3] } of clubs) {
        const key = `${season}|${league}|${id}`
        if (seen.has(key)) continue
        seen.add(key)
        const filePrefix = prefix || id
        const kitUrls = Object.fromEntries(kits.map(n => [n, kitUrl(dir, `${filePrefix}${sep}${n}.png`)]))
        const altUrls = (altByClub[canonical(id)] || []).map(f => kitUrl(dir, f))
        result.push({ ...lookup(id), kind, season, league, kitUrls, kits, altUrls })
      }
    }
  }
  return result
}

const kitLabels = { 1: 'domowa', 2: 'wyjazdowa', 3: 'trzecia', alt: 'alternatywna' }

// Every kit image of the pool as a question: { key, club, kitLabel, imageUrl }
function kitQuestions(clubs, selectedKitTypes) {
  const typeNums = selectedKitTypes.filter(t => typeof t === 'number')
  const includeAlt = selectedKitTypes.includes('alt')
  const questions = []

  for (const c of clubs) {
    for (const n of (c.kits || [1, 2, 3]).filter(k => typeNums.includes(k))) {
      questions.push({ key: `${c.season}|${c.league}|${c.id}_${n}`, club: c, kitLabel: kitLabels[n], imageUrl: c.kitUrls[n] })
    }
    if (includeAlt) {
      (c.altUrls || []).forEach((url, i) => {
        questions.push({ key: `${c.season}|${c.league}|${c.id}_alt_${i}`, club: c, kitLabel: kitLabels.alt, imageUrl: url })
      })
    }
  }
  return questions
}

// Picks `size` random kits and preloads their images before the round starts (see deck.js).
// One kit per club comes first, so a club repeats only when the pool has fewer clubs than questions.
export function prepareKitDeck(clubs, selectedKitTypes, size, onProgress) {
  const seen = new Set()
  const firsts = [], rest = []
  for (const q of shuffle(kitQuestions(clubs, selectedKitTypes))) {
    (seen.has(q.club.id) ? rest : firsts).push(q)
    seen.add(q.club.id)
  }
  return prepareDeck([...firsts, ...rest], size, onProgress)
}

function normalize(str) {
  return str.toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9\s]/g, '')
    .trim()
}

export function getSuggestions(input, clubs) {
  const inp = normalize(input)
  if (inp.length < 1) return []
  const seen = new Set()
  return clubs.filter(c => {
    if (seen.has(c.id)) return false
    const targets = [c.name, ...c.aliases]
    if (targets.some(t => normalize(t).includes(inp))) { seen.add(c.id); return true }
    return false
  })
}

export function checkAnswer(input, club) {
  const inp = normalize(input).trim()
  if (inp.length < 2) return false
  return [club.name, ...club.aliases].some(t => {
    const n = normalize(t)
    return n === inp || n.split(/\s+/).includes(inp)
  })
}

// ── Brief scope ───────────────────────────────────
// { kind: 'club' | 'nation', regions: string[], leagues: string[], seasons: string[] | null, kits: (number|'alt')[] }
// regions holds continents and confederations together (their ids never clash), so switching kind keeps both.
// seasons === null means "the newest season available for the chosen competitions".

export const KIT_TYPE_OPTIONS = [
  [1, 'Dom'],
  [2, 'Wyjazd'],
  [3, 'Trzecia'],
  ['alt', 'Alt'],
]

export const TEAM_KIND_OPTIONS = [
  ['club', 'Kluby'],
  ['nation', 'Reprezentacje'],
]

// Nothing but the region is preselected — the user has to pick leagues on their own.
export function defaultKitScope() {
  const clubRegions = getRegions('club')
  return {
    kind: 'club',
    regions: clubRegions.includes('europe') ? ['europe'] : [],
    leagues: [],
    seasons: null,
    kits: KIT_TYPE_OPTIONS.map(([id]) => id),
  }
}

export function selectedRegions(scope) {
  return getRegions(scope.kind).filter(r => scope.regions.includes(r))
}

// League keys the quiz draws from: chosen leagues of chosen continents, or chosen confederations.
export function selectedCompetitions(scope) {
  const regions = selectedRegions(scope)
  if (scope.kind === 'nation') return regions
  return getLeaguesIn(regions).filter(l => scope.leagues.includes(l))
}

export function selectedSeasons(scope) {
  const available = getSeasonsFor(selectedCompetitions(scope))
  return scope.seasons === null ? available.slice(0, 1) : available.filter(s => scope.seasons.includes(s))
}

// Clubs/nations of the scope; empty when the scope is incomplete (buildClubList treats [] as "all").
export function buildKitPool(scope) {
  const competitions = selectedCompetitions(scope)
  const seasons = selectedSeasons(scope)
  return competitions.length && seasons.length ? buildClubList(seasons, competitions) : []
}
